import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [x - 1 for x in data[2:]]
    indeg = [0] * n
    for v in a:
        indeg[v] += 1

    q = deque(i for i in range(n) if indeg[i] == 0)
    # dp[v][k-1] counts assignments in the processed trees at v,
    # when the value at v is k. None represents an all-ones array.
    dp = [None] * n
    while q:
        v = q.popleft()
        p = a[v]
        child = dp[v]
        parent = dp[p]
        if child is None:
            if parent is None:
                dp[p] = list(range(1, m + 1))
            else:
                for k in range(m):
                    parent[k] = parent[k] * (k + 1) % MOD
        else:
            s = 0
            if parent is None:
                for k in range(m):
                    s = (s + child[k]) % MOD
                    child[k] = s
                dp[p] = child
            else:
                for k in range(m):
                    s = (s + child[k]) % MOD
                    parent[k] = parent[k] * s % MOD
        dp[v] = None
        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)

    # Every remaining component is a directed cycle. All its values
    # must be equal, so multiply its arrays pointwise and then sum.
    ans = 1
    for i in range(n):
        if indeg[i] == 0:
            continue
        product = None
        v = i
        while indeg[v]:
            indeg[v] = 0
            cur = dp[v]
            if cur is not None:
                if product is None:
                    product = cur
                else:
                    for k in range(m):
                        product[k] = product[k] * cur[k] % MOD
            v = a[v]
        total = m if product is None else sum(product) % MOD
        ans = ans * total % MOD
    print(ans)


if __name__ == '__main__':
    main()

