        g=0
        for e in es: g=math.gcd(g,e)
        if g>1:
            p=pow(p,g,MOD)
            es=[e//g for e in es]
        total=sum(es)
        powers=[1]*(total+1)
        for h in range(1,total+1): powers[h]=powers[h-1]*p%MOD
        dp=[1]; m=0
        for i,e in enumerate(es,1):
