import sys
from math import isqrt


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    m = max(a)
    spf = list(range(m + 1))
    for p in range(2, isqrt(m) + 1):
        if spf[p] == p:
            for v in range(p * p, m + 1, p):
                if spf[v] == v:
                    spf[v] = p

    # The Grundy value is the number of prime factors with multiplicity.
    omega = bytearray(m + 1)
    for v in range(2, m + 1):
        omega[v] = omega[v // spf[v]] + 1

    result = 0
    for v in a:
        result ^= omega[v]
    print('Anna' if result else 'Bruno')


if __name__ == '__main__':
    main()

