import sys


def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(data)
    q = next(data)
    parent = [-1] * (n + 1)
    left = list(range(n + 1))
    right = list(range(n + 1))
    color = list(range(n + 1))
    count = [1] * (n + 1)

    def find(x):
        while parent[x] >= 0:
            p = parent[x]
            if parent[p] >= 0:
                parent[x] = parent[p]
            x = p
        return x

    def merge(a, b):
        if parent[a] > parent[b]:
            a, b = b, a
        parent[a] += parent[b]
        parent[b] = a
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    out = []
    for _ in range(q):
        typ = next(data)
        if typ == 2:
            out.append(str(count[next(data)]))
        else:
            x = next(data)
            c = next(data)
            r = find(x)
            old = color[r]
            if old == c:
                continue
            size = -parent[r]
            count[old] -= size
            count[c] += size
            color[r] = c
            if left[r] > 1:
                t = find(left[r] - 1)
                if color[t] == c:
                    r = merge(r, t)
            if right[r] < n:
                t = find(right[r] + 1)
                if color[t] == c:
                    r = merge(r, t)
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    main()

