import sys


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    q = next(it)
    edges = [(next(it) - 1, next(it) - 1, next(it)) for _ in range(m)]
    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            closed[e] = True
            queries.append((1, e))
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**18
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a, b, c) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = c

    # Floyd-Warshall, maintaining the symmetry of the distance matrix.
    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            v = di[k]
            if v == inf:
                continue
            for j in range(i + 1, n):
                z = v + dk[j]
                if z < di[j]:
                    di[j] = d[j][i] = z

    ans = []
    for query in reversed(queries):
        if query[0] == 2:
            z = d[query[1]][query[2]]
            ans.append(str(z if z < inf else -1))
        else:
            a, b, c = edges[query[1]]
            if c >= d[a][b]:
                continue
            # Snapshot distances before restoring this road.
            da = d[a][:]
            db = d[b][:]
            for i in range(n):
                di = d[i]
                va = da[i] + c
                vb = db[i] + c
                for j in range(i + 1, n):
                    z = va + db[j]
                    w = vb + da[j]
                    if w < z:
                        z = w
                    if z < di[j]:
                        di[j] = d[j][i] = z

    sys.stdout.write('\n'.join(reversed(ans)))


if __name__ == '__main__':
    solve()

