import sys
from math import gcd


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    rows = []
    upper = 10**9 + 1
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # The first machine has at least as good a capacity/cost ratio.
        if p * b > q * a:
            a, p, b, q = b, q, a, p
        # Any a/gcd(a,b) second machines can be replaced without
        # increasing cost, so only smaller counts need consideration.
        rows.append((a, p, b, q, a // gcd(a, b) - 1))
        upper = min(upper, max(a, b) * (budget // min(p, q)) + 1)

    def feasible(w):
        total = 0
        for a, p, b, q, limit in rows:
            best = ((w + a - 1) // a) * p
            for t in range(1, min(limit, (w + b - 1) // b) + 1):
                remaining = w - t * b
                cost = t * q
                if remaining > 0:
                    cost += ((remaining + a - 1) // a) * p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    low = 0
    while upper - low > 1:
        mid = (low + upper) // 2
        if feasible(mid):
            low = mid
        else:
            upper = mid
    print(low)


