class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 1000000007
        limit = min(n, x)
        dp = [0] * (limit + 1)
        dp[0] = 1
        factors = [0] + [(x - k + 1) * y for k in range(1, limit + 1)]
        for i in range(1, n + 1):
            for k in range(min(i, limit), 0, -1):
                dp[k] = (k * dp[k] + factors[k] * dp[k - 1]) % mod
            dp[0] = 0
        return sum(dp) % mod

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)
        depth = [0] * (length + 1)
        for x in range(2, length + 1):
            depth[x] = depth[x.bit_count()] + 1
        good = [x for x in range(1, length + 1) if depth[x] < k]
        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % mod
        inv = [1] * (length + 1)
        inv[length] = pow(fact[length], mod - 2, mod)
        for i in range(length, 0, -1):
            inv[i - 1] = inv[i] * i % mod
        answer = 0
        prefix = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = length - i - 1
                total = 0
                for ones in good:
                    j = ones - prefix
                    if j < 0:
                        continue
                    if j > remaining:
                        break
                    total += inv[j] * inv[remaining - j] % mod
                answer = (answer + fact[remaining] * total) % mod
                prefix += 1
        return answer

