import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    rows = [0] * n
    for i in range(m):
        u, v = data[2 + 2 * i] - 1, data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        bit = 1 << col
        p = next((i for i in range(rank, n) if rows[i] & bit), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        for i in range(n):
            if i != rank and rows[i] & bit:
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    # Put each nullspace basis vector into a separate output bit.
    pivot_set = set(pivots)
    free = [i for i in range(n) if i not in pivot_set]
    ans = [0] * n
    for k, col in enumerate(free):
        ans[col] = 1 << k
        for r, p in enumerate(pivots):
            if rows[r] & (1 << col):
                ans[p] |= 1 << k

    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)


if __name__ == '__main__':
    main()

