class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odd, even = (n + 1) // 2, n // 2
        total = fact[odd] * fact[even] * (2 if n % 2 == 0 else 1)
        if k > total:
            return []

        available = list(range(1, n + 1))
        result = []
        required = 1 if n % 2 else None

        while available:
            for i, value in enumerate(available):
                parity = value % 2
                if required is not None and parity != required:
                    continue
                remaining_odd = odd - parity
                remaining_even = even - (1 - parity)
                count = fact[remaining_odd] * fact[remaining_even]
                if k > count:
                    k -= count
                else:
                    result.append(value)
                    available.pop(i)
                    odd, even = remaining_odd, remaining_even
                    required = 1 - parity
                    break

        return result

