def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    down=[]; up=[]; common=[]
    for i in range(n):
        a=data[1+i]; b=data[1+n+i]; c=data[1+2*n+i]
        if a and b: common.append(c)
        elif a: down.append(c)
        elif b: up.append(c)
    down.sort(); up.sort(); common.sort(reverse=True)
    total=sum(common)
    active=total+sum(down)
    cost=0
    for c in reversed(down):
        active-=c
        cost+=active
    for c in up:
        active+=c
        cost+=active
    answer=cost
    pd=[0]; pu=[0]
    for c in down: pd.append(pd[-1]+c)
    for c in up: pu.append(pu[-1]+c)
    for c in common:
        d=bisect_right(down,c); u=bisect_right(up,c)
        cost+=2*total-c+pd[d]+pu[u]-c*(d+u)
        total-=c
        if cost<answer: answer=cost
    print(answer)

