    def largestPalindrome(self, n: int, k: int) -> str:
        if k in (1, 3, 9):
            return '9' * n

        if k == 2:
            return '8' if n == 1 else '8' + '9' * (n - 2) + '8'

        if k == 5:
            return '5' if n == 1 else '5' + '9' * (n - 2) + '5'

        if k == 4:
            return '8' * n if n <= 4 else '88' + '9' * (n - 4) + '88'

        if k == 8:
            return '8' * n if n <= 6 else '888' + '9' * (n - 6) + '888'

        if k == 6:
            if n <= 2:
                return '6' * n
            if n % 2:
                side = '8' + '9' * (n // 2 - 1)
                return side + '8' + side[::-1]
            side = '8' + '9' * (n // 2 - 2)
            return side + '77' + side[::-1]

        # For k = 7, changing only the middle digit or middle pair
        # suffices: its place-value coefficient is invertible modulo 7.
        remainder = (pow(10, n, 7) - 1) % 7
        if n % 2:
            coefficient = pow(10, n // 2, 7)
        else:
            coefficient = 11 * pow(10, n // 2 - 1, 7) % 7

        for delta in range(7):
            if (remainder - delta * coefficient) % 7 == 0:
                digit = str(9 - delta)
                side = '9' * ((n - 1) // 2)
                return side + digit * (1 if n % 2 else 2) + side

