from functools import cmp_to_key


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    counts = {}
    for i in range(2, len(data), 2):
        pair = (data[i], data[i + 1])
        counts[pair] = min(k, counts.get(pair, 0) + 1)

    # Functions are processed from innermost to outermost.
    def compare(f, g):
        return (f[0] - 1) * g[1] - (g[0] - 1) * f[1]

    pairs = sorted(counts, key=cmp_to_key(compare))
    dp = [-1] * (k + 1)
    dp[0] = 1
    used = 0
    for a, b in pairs:
        for _ in range(counts[(a, b)]):
            used += 1
            for j in range(min(k, used), 0, -1):
                value = a * dp[j - 1] + b
                if value > dp[j]:
                    dp[j] = value
    print(dp[k])


