class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        grouped = [[] for _ in range(n)]
        for k, (l, r) in enumerate(queries):
            grouped[l].append((r, k))
        answer = [0] * len(queries)
        score = [0] * n
        best = [0] * n
        for l in range(n - 1, -1, -1):
            value = nums[l]
            score[l] = value
            best[l] = value
            maximum = value
            for r in range(l + 1, n):
                value ^= score[r]
                score[r] = value
                if best[r] > maximum:
                    maximum = best[r]
                if value > maximum:
                    maximum = value
                best[r] = maximum
            for r, k in grouped[l]:
                answer[k] = best[r]
        return answer

