    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            m = len(t)
            if not m:
                return range(n + 1)
            if m > n:
                return []
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        j = k = 0
        la, lb, lc = len(a), len(b), len(c)
        ans = n + 1
        for start in aa:
            while j < len(bb) and bb[j] < start + la:
                j += 1
            if j == len(bb):
                break
            end_b = bb[j] + lb
            while k < len(cc) and cc[k] < end_b:
                k += 1
            if k == len(cc):
                break
            ans = min(ans, cc[k] + lc - start)
        return ans if ans <= n else -1

