import heapq


def solve(W, groups):
    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        gains = [0]
        for _ in range(W // w):
            val = -heap[0]
            if val <= 0:
                break
            gains.append(gains[-1] + val)
            heapq.heapreplace(heap, 2 - val)
        count = len(gains) - 1
        if count == 0:
            continue
        if count == 1:
