from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            if x >= 0:
                start[x] = len(order)
                stack.append(~x)
                stack.extend(reversed(children[x]))
            else:
                x = ~x
                order.append(s[x])
                end[x] = len(order)
        t = '#' + '#'.join(order) + '#'
        m = len(t)
        radius = [0] * m
        center = right = 0
        for i in range(m):
            k = min(radius[2 * center - i], right - i) if i < right else 0
            while i - k - 1 >= 0 and i + k + 1 < m and t[i - k - 1] == t[i + k + 1]:
                k += 1
            radius[i] = k
            if i + k > right:
                center, right = i, i + k
        return [radius[start[i] + end[i]] >= end[i] - start[i] for i in range(n)]

