    g = [[] for _ in range(n)]
    for i in range(4, len(data), 2):
        u = data[i] - 1
        v = data[i + 1] - 1
        g[u].append(v)
        g[v].append(u)
    del data

    a = [-1] * n
    a[s] = 0
    count = [0] * n
    count[s] = 1
    parent = [-1] * n
    q = [s]
    for u in q:
        nd = a[u] + 1
        for v in g[u]:
            if a[v] < 0:
                a[v] = nd
                parent[v] = u
                q.append(v)
            if a[v] == nd:
                count[v] = min(2, count[v] + count[u])

    d = a[t]
    if count[t] == 2:
        print(2 * d)
        return

    b = [-1] * n
    b[t] = 0
    q = [t]
    for u in q:
        nd = b[u] + 1
        for v in g[u]:
            if b[v] < 0:
                b[v] = nd
                q.append(v)

