    for u in range(n):
        for v in g[u]:
            if a[u] == a[v] and a[u] + b[v] == d:
                print(2 * d + 1)
                return

    blocked = bytearray(n)
    u = parent[t]
    while u != s:
        if len(g[u]) >= 3:
            print(2 * d + 2)
            return
        blocked[u] = 1
        u = parent[u]

    # All internal vertices of the unique shortest path have degree two.
    # Passing is possible either around an alternative route, or at a
    # branching vertex reached beyond one of the endpoints.
    ans = 10**18
    for v in range(n):
        if len(g[v]) >= 3:
            ans = min(ans, 2 * d + 4 * min(a[v], b[v]) + 4)

    c = [-1] * n
    c[s] = 0
    q = [s]
    for u in q:
