class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7

        # lengths[k] is the length obtained from 'a' after k steps.
        lengths = [1] * (t + 26)
        for k in range(26, t + 26):
            lengths[k] = (lengths[k - 26] + lengths[k - 25]) % MOD

        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        # Starting at letter i is equivalent to starting 'a' i steps earlier.
        return sum(counts[i] * lengths[t + i] for i in range(26)) % MOD

