from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        active = [i for i, x in enumerate(nums) if x]
        if not active:
            return 0

        # Bit s is set exactly when sum s is achievable at this index.
        dp = [1] * len(nums)
        masks = [(1 << (x + 1)) - 1 for x in nums]
        targets = [1 << x for x in nums]

        for k, (l, r, v) in enumerate(queries, 1):
            remaining = []
            for i in active:
                if l <= i <= r:
                    dp[i] = (dp[i] | (dp[i] << v)) & masks[i]
                if not dp[i] & targets[i]:
                    remaining.append(i)
            active = remaining
            if not active:
                return k
        return -1

