from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # Count splits satisfying the first prefix condition.
        pref = [0] * (n + 1)
        answer = 0
        for i in range(1, n):
            good = z[i] >= i
            pref[i] = pref[i - 1] + good
            if good and 2 * i < n:
                answer += n - 2 * i

        # Fix the length k of the middle subarray. Equal runs between
        # nums[x] and nums[x+k] identify all possible middle starts.
        for k in range(1, (n - 1) // 2 + 1):
            start = 1
            for x in range(1, n - k):
                if nums[x] != nums[x + k]:
                    end = x - k
                    if end >= start:
                        answer += end - start + 1
                        hi = min(end, k)
                        if hi >= start:
                            answer -= pref[hi] - pref[start - 1]
                    start = x + 1

            end = n - 2 * k
            if end >= start:
                answer += end - start + 1
