from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        positions = [[] for _ in range(26)]
        for j in range(m - 1, -1, -1):
            positions[ord(pattern[j]) - 97].append(j)

        targeted = bytearray(len(source))
        for i in targetIndices:
            targeted[i] = 1

        # dp[j]: minimum number of targeted positions used to match
        # the first j pattern characters in the processed source prefix.
        dp = [m + 1] * (m + 1)
        dp[0] = 0
        for i, ch in enumerate(source):
            cost = targeted[i]
            # Descending order prevents using this source position twice.
            for j in positions[ord(ch) - 97]:
                candidate = dp[j] + cost
                if candidate < dp[j + 1]:
                    dp[j + 1] = candidate

        return len(targetIndices) - dp[m]

