class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        active = s.count('1')
        previous = current = best = 0

        # A trailing sentinel finishes the last zero run.
        for ch in s + '1':
            if ch == '0':
                current += 1
            elif current:
                # Removing the intervening one run merges these zero runs.
                # Filling the merged run gains exactly their combined length.
                if previous:
                    best = max(best, previous + current)
